			t.Fatalf("entry = %q / %+v", api.RuntimePresence, api.Attention)
		}
		if len(api.Sessions) != 1 || api.Sessions[0].Kind != SessionKindCheckoutDirect {
			t.Fatalf("attribution failed: %+v", api.Sessions)
