// TestAgentStatusCheckoutPresenceInvariant is the checkout twin of
// TestAgentStatusPresenceInvariant: every stale or unknown presence, at every
// level, coincides with needs_attention, and the summary counters still sum to
// the entry count. Every entry has a real git ref so no ref-missing warning
// can make the assertion pass vacuously.
func TestAgentStatusCheckoutPresenceInvariant(t *testing.T) {
	cases := []struct {
		name string
		body string
		pid  int
		live ProcessLiveness
		tmux TmuxInventoryProbe
	}{
		{name: "owner dead", body: `{"schema_version":1,"feature":"auth","name":"api","mode":"direct","pid":999080,"stage":"agent"}`, pid: 999080, live: ProcessDead},
		{name: "owner eperm", body: `{"schema_version":1,"feature":"auth","name":"api","mode":"direct","pid":999081,"stage":"agent"}`, pid: 999081, live: ProcessUnknown},
		{name: "tmux gone", body: `{"schema_version":1,"feature":"auth","name":"api","mode":"tmux","tmux_session":"s","stage":"tmux"}`},
		{name: "tmux unverifiable", body: `{"schema_version":1,"feature":"auth","name":"api","mode":"tmux","tmux_session":"s","stage":"tmux"}`,
			tmux: fakeTmuxInventory{snap: TmuxSnapshot{Sessions: map[string]bool{}}}},
		{name: "state invalid", body: "not json"},
		{name: "state unsupported", body: `{"schema_version":99,"feature":"auth","name":"api","mode":"direct","pid":1,"stage":"agent"}`},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			_, ws := setupCheckoutSessionRepo(t, "auth", "api")
			writeCheckoutSessionState(t, ws, c.body)
			writeCheckoutSessionLock(t, ws)

			var proc ProcessProber
			if c.pid != 0 {
				proc = fakeProcessProber{probe: map[int]ProcessLiveness{c.pid: c.live}}
			}
			r := buildStatus(t, ws, statusOpts(proc, c.tmux))

			// Nothing may be silently healthy: the record is never usable.
			if r.Workspace.Attention.Status != AttentionNeedsAttention {
				t.Fatalf("workspace attention = %q\nissues %v", r.Workspace.Attention.Status, issueCodes(r))
			}
			assertNoSilentPresence := func(level string, presence RuntimePresence, status AttentionStatus) {
				t.Helper()
				if presence == PresenceStale || presence == PresenceUnknown {
					if status != AttentionNeedsAttention {
						t.Fatalf("%s is %q but %q\nissues %v", level, presence, status, issueCodes(r))
					}
				}
			}
			assertNoSilentPresence("workspace", r.Workspace.RuntimePresence, r.Workspace.Attention.Status)
			for _, f := range r.Features {
				assertNoSilentPresence("feature "+f.Feature, f.RuntimePresence, f.Attention.Status)
				for _, e := range f.Entries {
					assertNoSilentPresence("entry "+e.Feature+"/"+e.Name, e.RuntimePresence, e.Attention.Status)
					if e.Materialization.RefExists == nil || !*e.Materialization.RefExists {
						t.Fatalf("the fixture must have a real ref for %s, or ref-missing masks the verdict", e.Name)
					}
				}
			}
			if r.Summary.NeedsAttention+r.Summary.Active+r.Summary.Idle != r.Summary.Entries {
				t.Fatalf("attention counters must sum to entries: %+v", r.Summary)
			}
			if r.Summary.RuntimePresent+r.Summary.RuntimeStale+r.Summary.RuntimeUnknown+r.Summary.RuntimeAbsent != r.Summary.Entries {
				t.Fatalf("runtime counters must sum to entries: %+v", r.Summary)
			}
		})
	}
}

// ---------- external materialization edge cases ----------

func TestAgentStatusExternalWorktreeEdgeCases(t *testing.T) {
	t.Run("path is not a directory", func(t *testing.T) {
		entries := []StackEntry{{Name: "api", Base: "main"}}
		ws, featurePath := setupExternalStatusWorkspace(t, "auth", entries)
		wtPath := filepath.Join(featurePath, "worktrees", "api")
		if err := os.MkdirAll(filepath.Dir(wtPath), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(wtPath, []byte("not a worktree"), 0644); err != nil {
			t.Fatal(err)
		}
		r := buildStatus(t, ws, statusOpts(nil, nil))
		api := findEntry(t, r, "auth", "api")
		if api.Materialization.State != MaterializedUnknown {
			t.Fatalf("state = %q, want unknown", api.Materialization.State)
		}
		if api.Materialization.Path == nil || *api.Materialization.Path != wtPath {
			t.Fatalf("path = %v", api.Materialization.Path)
		}
		if api.Materialization.Dirty != nil || api.Materialization.CheckedOutBranch != nil {
			t.Fatal("a non-directory must be probed for nothing")
		}
		iss := hasIssue(r, IssueWorktreeUnreadable)
		if iss == nil || iss.Scope != ScopeEntry {
			t.Fatalf("expected an entry-scoped worktree-unreadable, got %v", issueCodes(r))
		}
		if api.Attention.Status != AttentionNeedsAttention {
			t.Fatalf("attention = %q", api.Attention.Status)
		}
	})

	t.Run("rev-parse failure in a present directory", func(t *testing.T) {
		entries := []StackEntry{{Name: "api", Base: "main"}}
		ws, featurePath := setupExternalStatusWorkspace(t, "auth", entries)
		// A real directory that is not a Git worktree: healthCurrentBranch
		// fails, so the dirty probe must not run and claim "clean".
		wtPath := filepath.Join(featurePath, "worktrees", "api")
		if err := os.MkdirAll(wtPath, 0755); err != nil {
			t.Fatal(err)
		}
		r := buildStatus(t, ws, statusOpts(nil, nil))
		api := findEntry(t, r, "auth", "api")
		if api.Materialization.State != MaterializedPresent {
			t.Fatalf("state = %q, want present", api.Materialization.State)
		}
		if api.Materialization.Dirty != nil {
			t.Fatalf("a failed branch probe must not report dirtiness: %v", *api.Materialization.Dirty)
		}
		if api.Materialization.CheckedOutBranch != nil {
			t.Fatalf("checked_out_branch = %v", *api.Materialization.CheckedOutBranch)
		}
		if hasIssue(r, IssueWorktreeUnreadable) == nil {
			t.Fatalf("expected worktree-unreadable, got %v", issueCodes(r))
		}
		if hasIssue(r, IssueWorktreeWrongBranch) != nil {
			t.Fatal("an unreadable worktree can never be on the wrong branch")
		}
	})

	t.Run("detached worktree", func(t *testing.T) {
		entries := []StackEntry{{Name: "api", Base: "main"}}
		ws, featurePath := setupExternalStatusWorkspace(t, "auth", entries)
		wtPath := addExternalWorktree(t, ws, featurePath, entries[0])
		head := gitInTest(t, wtPath, "rev-parse", "HEAD")
		gitInTest(t, wtPath, "checkout", "--detach", head)

		r := buildStatus(t, ws, statusOpts(nil, nil))
		api := findEntry(t, r, "auth", "api")
		if api.Materialization.State != MaterializedPresent {
			t.Fatalf("state = %q, want present", api.Materialization.State)
		}
		if api.Materialization.CheckedOutBranch != nil {
			t.Fatalf("a detached worktree names no branch, got %q", *api.Materialization.CheckedOutBranch)
		}
		if hasIssue(r, IssueWorktreeWrongBranch) != nil {
			t.Fatal("a detached HEAD is not a wrong branch")
		}
		if api.Materialization.Dirty == nil {
			t.Fatal("a detached but readable worktree is still probed for dirtiness")
		}
		if api.Attention.Status != AttentionIdle {
			t.Fatalf("attention = %q, want idle\nissues %v", api.Attention.Status, issueCodes(r))
		}
	})
}

// ---------- JSON key-set snapshots ----------

// assertAgentStatusKeySets walks a decoded document and asserts the exact key
// set of every level it reaches. It is the shared body of the populated and
// empty snapshots in both workspace modes.
func assertAgentStatusKeySets(t *testing.T, doc map[string]any) {
	t.Helper()
	assertKeys(t, "report", doc, []string{"schema_version", "generated_at", "workspace", "features", "issues", "summary"})
	assertKeys(t, "workspace", doc["workspace"].(map[string]any), []string{
		"mode", "stable_id", "repo_root", "metadata_root", "degraded", "degraded_reason", "branch",
		"detached", "dirty", "active_git_op", "tmux", "checkout_session", "runtime_presence",
		"agent_state", "attention",
	})
	assertKeys(t, "workspace.tmux", doc["workspace"].(map[string]any)["tmux"].(map[string]any), []string{
		"available", "server_running", "session_count", "path_verification",
	})
	assertKeys(t, "workspace.attention", doc["workspace"].(map[string]any)["attention"].(map[string]any), []string{
		"status", "issue_count", "codes",
	})
	assertKeys(t, "summary", doc["summary"].(map[string]any), []string{
		"features", "entries", "needs_attention", "active", "idle", "runtime_present",
		"runtime_stale", "runtime_unknown", "runtime_absent", "issues", "warnings", "errors",
	})
	if session, ok := doc["workspace"].(map[string]any)["checkout_session"].(map[string]any); ok {
		assertKeys(t, "workspace.checkout_session", session, agentStatusSessionKeys)
	}
	for _, raw := range doc["features"].([]any) {
		feature := raw.(map[string]any)
		assertKeys(t, "feature", feature, []string{
			"feature", "path", "stack_state", "sync", "feature_tmux", "entries",
			"runtime_presence", "agent_state", "attention",
		})
		assertKeys(t, "feature.attention", feature["attention"].(map[string]any), []string{
			"status", "issue_count", "codes",
		})
		if sync, ok := feature["sync"].(map[string]any); ok {
			assertKeys(t, "feature.sync", sync, []string{
				"kind", "stage", "liveness", "failure_reason", "current_branch", "failed_branch",
				"lock_pid", "lock_live", "pending", "completed", "skipped",
			})
		}
		if tmux, ok := feature["feature_tmux"].(map[string]any); ok {
			assertKeys(t, "feature.feature_tmux", tmux, agentStatusSessionKeys)
		}
		for _, rawEntry := range feature["entries"].([]any) {
			entry := rawEntry.(map[string]any)
			assertKeys(t, "entry", entry, []string{
				"feature", "name", "git_branch", "base", "base_git_branch", "repo", "archived",
				"is_current_checkout", "materialization", "sessions", "session_counts",
				"unread_decisions", "runtime_presence", "agent_state", "attention", "feature_attention",
			})
			assertKeys(t, "materialization", entry["materialization"].(map[string]any), []string{
				"kind", "state", "path", "ref_exists", "checked_out_branch", "dirty",
			})
			assertKeys(t, "session_counts", entry["session_counts"].(map[string]any), []string{
				"total", "live", "stale", "unknown", "invalid",
			})
			assertKeys(t, "entry.attention", entry["attention"].(map[string]any), []string{
				"status", "issue_count", "codes",
			})
			for _, rawSession := range entry["sessions"].([]any) {
				assertKeys(t, "session", rawSession.(map[string]any), agentStatusSessionKeys)
			}
		}
	}
	for _, rawIssue := range doc["issues"].([]any) {
		assertKeys(t, "issue", rawIssue.(map[string]any), []string{
			"code", "severity", "scope", "feature", "name", "message", "guidance",
		})
	}
}

var agentStatusSessionKeys = []string{
	"kind", "presence", "agent_state", "stage", "stage_recognized", "owner_pid", "child_pid",
	"liveness", "tmux_session", "path", "agent", "started_at", "updated_at", "record_id",
	"record_state", "detail",
}

func decodeStatus(t *testing.T, r *AgentStatusReport) map[string]any {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(encodeStatus(t, r), &doc); err != nil {
		t.Fatal(err)
	}
	return doc
}

// TestAgentStatusJSONKeySetSnapshots asserts the exact key set at every level
// for the three shapes a consumer must never see drift: a populated external
// document, a populated checkout document, and an empty workspace.
func TestAgentStatusJSONKeySetSnapshots(t *testing.T) {
	t.Run("external populated", func(t *testing.T) {
		entries := []StackEntry{{Name: "api", Branch: "jd/api", Base: "main"}}
		ws, featurePath := setupExternalStatusWorkspace(t, "auth", entries)
		addExternalWorktree(t, ws, featurePath, entries[0])
		mustCreateRecord(t, featurePath, DirectSessionRecord{Feature: "auth", Name: "api", Stage: DirectStageAgent})
		if err := os.WriteFile(SyncStatePath(featurePath), []byte("pending: [api]\n"), 0644); err != nil {
			t.Fatal(err)
		}
		tmux := fakeTmuxInventory{snap: TmuxSnapshot{
			Available: true, ServerRunning: true, PanesAvailable: true,
			Sessions: map[string]bool{
				ExternalTmuxSessionName("auth", "api"): true,
				ExternalFeatureTmuxSessionName("auth"): true,
			},
			Panes: []TmuxPane{
				{Session: ExternalTmuxSessionName("auth", "api"), Path: filepath.Join(featurePath, "worktrees", "api")},
				{Session: ExternalFeatureTmuxSessionName("auth"), Path: featurePath},
			},
		}}
		proc := fakeProcessProber{probe: map[int]ProcessLiveness{os.Getpid(): ProcessLive}}
		r := buildStatus(t, ws, statusOpts(proc, tmux))
		doc := decodeStatus(t, r)
		feature := doc["features"].([]any)[0].(map[string]any)
		if feature["sync"] == nil || feature["feature_tmux"] == nil {
			t.Fatalf("the populated fixture must exercise sync and feature_tmux: %v", feature)
		}
		if len(doc["issues"].([]any)) == 0 {
			t.Fatal("the populated fixture must carry at least one issue")
		}
		assertAgentStatusKeySets(t, doc)
	})

	t.Run("checkout populated", func(t *testing.T) {
		dir, ws := setupHealthTestRepo(t)
		addStackEntries(t, ws, "auth", []StackEntry{{Name: "api", Branch: "jd/api", Base: "main"}})
		gitInTest(t, dir, "branch", "jd/api")
		writeCheckoutSessionState(t, ws, `{"schema_version":1,"feature":"auth","name":"api","mode":"direct","pid":999090,"stage":"agent","started_at":"2020-01-01T00:00:00Z"}`)
		writeCheckoutSessionLock(t, ws)
		proc := fakeProcessProber{probe: map[int]ProcessLiveness{999090: ProcessLive}}
		r := buildStatus(t, ws, statusOpts(proc, nil))
		doc := decodeStatus(t, r)
		workspace := doc["workspace"].(map[string]any)
		if workspace["checkout_session"] == nil {
			t.Fatal("the checkout fixture must carry a checkout_session")
		}
		entry := doc["features"].([]any)[0].(map[string]any)["entries"].([]any)[0].(map[string]any)
		if len(entry["sessions"].([]any)) != 1 {
			t.Fatalf("the checkout session must be attributed: %v", entry["sessions"])
		}
		assertAgentStatusKeySets(t, doc)
	})

	t.Run("empty workspace", func(t *testing.T) {
		ws := Workspace{Mode: ModeExternal, MetadataRoot: t.TempDir(), Caps: capsFor(ModeExternal)}
		r := buildStatus(t, ws, statusOpts(nil, nil))
		doc := decodeStatus(t, r)
		if len(doc["features"].([]any)) != 0 {
			t.Fatal("the empty fixture must have no feature")
		}
		workspace := doc["workspace"].(map[string]any)
		for _, key := range []string{"checkout_session", "repo_root", "stable_id", "branch", "detached", "dirty", "active_git_op", "degraded_reason"} {
			if workspace[key] != nil {
				t.Fatalf("workspace.%s = %v, want null", key, workspace[key])
			}
		}
		assertAgentStatusKeySets(t, doc)
	})
}

// TestFormatAgentStatusKeepsOneIssuePerLine asserts a message that quotes a
// multi-line parser error still occupies exactly one line in the human view,
// while the JSON document keeps it verbatim.
func TestFormatAgentStatusKeepsOneIssuePerLine(t *testing.T) {
	entries := []StackEntry{{Name: "api", Base: "main"}}
	ws, featurePath := setupExternalStatusWorkspace(t, "auth", entries)
	addExternalWorktree(t, ws, featurePath, entries[0])
	if err := os.WriteFile(SyncStatePath(featurePath), []byte("::bad"), 0644); err != nil {
		t.Fatal(err)
	}
	r := buildStatus(t, ws, statusOpts(nil, nil))
	iss := hasIssue(r, IssueSyncStateInvalid)
	if iss == nil || !strings.Contains(iss.Message, "\n") {
		t.Skip("this yaml build does not produce a multi-line parser error")
	}
	out := FormatAgentStatus(r)
	for _, line := range strings.Split(out, "\n") {
		if strings.HasPrefix(line, "  [") && strings.Contains(line, IssueSyncStateInvalid) {
			if !strings.Contains(line, "inspect ") {
				t.Fatalf("the whole issue must be on one line: %q", line)
			}
			return
		}
	}
	t.Fatalf("the issue line was never rendered:\n%s", out)
}

package internal

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"

	"gopkg.in/yaml.v3"
)

// ---------- Process / tmux seams ----------

// ProcessChecker abstracts PID liveness for testing.
type ProcessChecker interface {
	Alive(pid int) bool
}

// ProcessLiveness is the three-valued result of probing a PID. It exists
// because a bare Signal(0) collapses "no such process" and "not permitted"
// into one answer, which misreports a live process owned by another user.
type ProcessLiveness string

const (
	// ProcessLive means a process with that PID exists. It does not prove the
	// process is the one that was recorded: PID reuse is an accepted limit.
	ProcessLive ProcessLiveness = "live"
	// ProcessDead means the process provably does not exist.
	ProcessDead ProcessLiveness = "dead"
	// ProcessUnknown means liveness could not be determined (for example
	// EPERM, when the PID belongs to another user).
	ProcessUnknown ProcessLiveness = "unknown"
)

// ProcessProber abstracts three-valued PID liveness for testing.
type ProcessProber interface {
	Probe(pid int) ProcessLiveness
}

// proberAsChecker adapts a ProcessProber to the two-valued ProcessChecker
// expected by the existing health helpers, so no second liveness
// implementation is needed.
type proberAsChecker struct{ p ProcessProber }

func (a proberAsChecker) Alive(pid int) bool { return a.p.Probe(pid) == ProcessLive }

// TmuxChecker abstracts tmux session liveness for testing.
type TmuxChecker interface {
	HasSession(name string) bool
}

type realProcessChecker struct{}

func (realProcessChecker) Probe(pid int) ProcessLiveness {
	if pid <= 0 {
		return ProcessDead
	}
	p, err := os.FindProcess(pid)
	if err != nil {
		return ProcessDead
	}
	err = p.Signal(syscall.Signal(0))
	switch {
	case err == nil:
		return ProcessLive
	case errors.Is(err, os.ErrProcessDone), errors.Is(err, syscall.ESRCH):
		return ProcessDead
	default:
		// EPERM and anything else: not provably dead.
		return ProcessUnknown
	}
}

func (r realProcessChecker) Alive(pid int) bool { return r.Probe(pid) == ProcessLive }

// NewProcessProber returns the real three-valued PID prober. It exists so
// internal/cli can inject a fake without exporting realProcessChecker.
func NewProcessProber() ProcessProber { return realProcessChecker{} }

type realTmuxChecker struct{}

func (realTmuxChecker) HasSession(name string) bool {
	return exec.Command("tmux", "has-session", "-t", name).Run() == nil
}

// ---------- Report severity ----------

// CheckoutSeverity distinguishes informational notes from actionable warnings.
type CheckoutSeverity string

const (
	SeverityOK      CheckoutSeverity = "ok"
	SeverityInfo    CheckoutSeverity = "info"
	SeverityWarning CheckoutSeverity = "warning"
	SeverityError   CheckoutSeverity = "error"
)

// ---------- Report sections ----------

// CheckoutWorkspaceHeader describes the workspace identity and current repo state.
type CheckoutWorkspaceHeader struct {
	Mode        WorkspaceMode `json:"mode"`
	StableID    string        `json:"stable_id"`
	RepoRoot    string        `json:"repo_root"`
	Metadata    string        `json:"metadata_root"`
	Branch      string        `json:"branch"`
	Detached    bool          `json:"detached"`
	Dirty       bool          `json:"dirty"`
	ActiveGitOp string        `json:"active_git_op,omitempty"` // merge, rebase, cherry-pick, revert, bisect
}

// CheckoutSyncReport describes a single checkout-sync state entry found in .tws/state.
type CheckoutSyncReport struct {
	Feature       string           `json:"feature"`
	Stage         string           `json:"stage"`
	FailureReason string           `json:"failure_reason,omitempty"`
	CurrentBranch string           `json:"current_branch,omitempty"`
	LockPID       int              `json:"lock_pid,omitempty"`
	LockLive      bool             `json:"lock_live"`
	Liveness      string           `json:"liveness"` // live, stale, invalid
	Guidance      string           `json:"guidance,omitempty"`
	Severity      CheckoutSeverity `json:"severity"`
}

// CheckoutSessionReport describes the checkout agent session and lock state.
type CheckoutSessionReport struct {
	Active      bool             `json:"active"`
	Feature     string           `json:"feature,omitempty"`
	Name        string           `json:"name,omitempty"`
	Mode        AgentSessionMode `json:"mode,omitempty"`
	PID         int              `json:"pid,omitempty"`
	TmuxSession string           `json:"tmux_session,omitempty"`
	OwnerLive   bool             `json:"owner_live"`
	LockHeld    bool             `json:"lock_held"`
	Liveness    string           `json:"liveness,omitempty"` // live, stale, mismatch
	Guidance    string           `json:"guidance,omitempty"`
	Severity    CheckoutSeverity `json:"severity"`
}

// AncestryStatus classifies the relationship between a branch and its base.
type AncestryStatus string

const (
	AncestryStatusCurrent   AncestryStatus = "current"
	AncestryStatusStale     AncestryStatus = "stale"
	AncestryStatusMissing   AncestryStatus = "missing"
	AncestryStatusDivergent AncestryStatus = "divergent"
	AncestryStatusCrossRepo AncestryStatus = "cross-repo-unsupported"
)

// CheckoutFeatureEntry describes a single stack entry in checkout mode.
type CheckoutFeatureEntry struct {
	Feature        string           `json:"feature"`
	Name           string           `json:"name"`
	GitBranch      string           `json:"git_branch"`
	Archived       bool             `json:"archived"`
	RefExists      bool             `json:"ref_exists"`
	Current        bool             `json:"current"`
	BaseName       string           `json:"base_name"`
	BaseGitBranch  string           `json:"base_git_branch"`
	AncestryStatus AncestryStatus   `json:"ancestry_status"`
	LocalHead      string           `json:"local_head,omitempty"`
	ParentHead     string           `json:"parent_head,omitempty"`
	Severity       CheckoutSeverity `json:"severity"`
}

// CheckoutContextLinkReport describes a single session context link.
type CheckoutContextLinkReport struct {
	Path     string           `json:"path"`
	Target   string           `json:"target"`
	Status   string           `json:"status"` // healthy, missing, replaced, not-symlink
	Severity CheckoutSeverity `json:"severity"`
}

// CheckoutHealthReport is the full read-only checkout doctor report.
type CheckoutHealthReport struct {
	Header   CheckoutWorkspaceHeader     `json:"header"`
	Sync     []CheckoutSyncReport        `json:"sync,omitempty"`
	Session  *CheckoutSessionReport      `json:"session,omitempty"`
	Features []CheckoutFeatureEntry      `json:"features,omitempty"`
	Links    []CheckoutContextLinkReport `json:"links,omitempty"`
	Issues   int                         `json:"issues"`
}

func (r *CheckoutHealthReport) HasErrors() bool {
	for _, sync := range r.Sync {
		if sync.Severity == SeverityError {
			return true
		}
	}
	if r.Session != nil && r.Session.Severity == SeverityError {
		return true
	}
	for _, entry := range r.Features {
		if entry.Severity == SeverityError {
			return true
		}
	}
	for _, link := range r.Links {
		if link.Severity == SeverityError {
			return true
		}
	}
	return false
}

func (r *CheckoutHealthReport) FilterFeature(feature string) error {
	var features []CheckoutFeatureEntry
	for _, entry := range r.Features {
		if entry.Feature == feature {
			features = append(features, entry)
		}
	}
	if len(features) == 0 {
		return fmt.Errorf("feature not found: %s", feature)
	}
	r.Features = features
	var sync []CheckoutSyncReport
	for _, entry := range r.Sync {
		if entry.Feature == feature {
			sync = append(sync, entry)
		}
	}
	r.Sync = sync
	if r.Session != nil && r.Session.Feature != feature {
		r.Session = nil
		r.Links = nil
	}
	r.Issues = countIssues(r)
	return nil
}

// ---------- Builder ----------

// CheckoutHealthOpts configures the health report builder for testing.
type CheckoutHealthOpts struct {
	Proc ProcessChecker
	Tmux TmuxChecker
}

func defaultOpts() CheckoutHealthOpts {
	return CheckoutHealthOpts{
		Proc: realProcessChecker{},
		Tmux: realTmuxChecker{},
	}
}

// BuildCheckoutHealthReport generates a read-only checkout health report.
// It never mutates Git state, locks, or files.
func BuildCheckoutHealthReport(ws Workspace, opts *CheckoutHealthOpts) (*CheckoutHealthReport, error) {
	if opts == nil {
		d := defaultOpts()
		opts = &d
	}
	if opts.Proc == nil {
		opts.Proc = realProcessChecker{}
	}
	if opts.Tmux == nil {
		opts.Tmux = realTmuxChecker{}
	}

	report := &CheckoutHealthReport{}

	// 1. Workspace header
	header, err := buildHeader(ws)
	if err != nil {
		return nil, fmt.Errorf("cannot read workspace: %w", err)
	}
	report.Header = header

	// 2. Sync state entries
	report.Sync = buildSyncReports(ws, opts.Proc)

	// 3. Session report
	report.Session = buildSessionReport(ws, opts.Proc, opts.Tmux)

	// 4. Feature entries
	features, fErr := buildFeatureEntries(ws)
	if fErr != nil {
		return nil, fmt.Errorf("cannot list features: %w", fErr)
	}
	report.Features = features

	// 5. Context links
	report.Links = buildContextLinks(ws)

	// 6. Count issues
	report.Issues = countIssues(report)

	return report, nil
}

// ---------- Header ----------

func buildHeader(ws Workspace) (CheckoutWorkspaceHeader, error) {
	h := CheckoutWorkspaceHeader{
		Mode:     ws.Mode,
		StableID: ws.StableID,
		RepoRoot: ws.RepoRoot,
		Metadata: ws.MetadataRoot,
	}

	// Current branch / detached
	branch, detached := healthCurrentBranch(ws.RepoRoot)
	h.Branch = branch
	h.Detached = detached

	// Dirty
	h.Dirty = gitDirty(ws.RepoRoot)

	// Active Git operation
	h.ActiveGitOp = gitActiveOp(ws.RepoRoot)

	return h, nil
}

func healthCurrentBranch(repo string) (string, bool) {
	out, err := exec.Command("git", "-C", repo, "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return "", false
	}
	b := strings.TrimSpace(string(out))
	if b == "HEAD" {
		// detached — try to get short SHA
		sha, sErr := exec.Command("git", "-C", repo, "rev-parse", "--short", "HEAD").Output()
		if sErr == nil {
			return strings.TrimSpace(string(sha)), true
		}
		return "HEAD", true
	}
	return b, false
}

func gitDirty(repo string) bool {
	out, err := exec.Command("git", "-C", repo, "status", "--porcelain").Output()
	if err != nil {
		return false
	}
	return len(strings.TrimSpace(string(out))) > 0
}

func gitActiveOp(repo string) string {
	gitDir := filepath.Join(repo, ".git")
	// Check if .git is a file (worktree) — resolve the actual git dir
	if info, err := os.Stat(gitDir); err == nil && !info.IsDir() {
		data, readErr := os.ReadFile(gitDir)
		if readErr == nil {
			line := strings.TrimSpace(string(data))
			if after, ok := strings.CutPrefix(line, "gitdir: "); ok {
				if !filepath.IsAbs(after) {
					after = filepath.Join(repo, after)
				}
				gitDir = filepath.Clean(after)
			}
		}
	}
	checks := []struct {
		marker string
		name   string
	}{
		{"rebase-merge", "rebase"},
		{"rebase-apply", "rebase"},
		{"MERGE_HEAD", "merge"},
		{"CHERRY_PICK_HEAD", "cherry-pick"},
		{"REVERT_HEAD", "revert"},
		{"BISECT_LOG", "bisect"},
	}
	for _, c := range checks {
		if _, err := os.Stat(filepath.Join(gitDir, c.marker)); err == nil {
			return c.name
		}
	}
	return ""
}

// ---------- Sync ----------

func buildSyncReports(ws Workspace, proc ProcessChecker) []CheckoutSyncReport {
	stateDir := ws.CheckoutStateDir()
	entries, err := os.ReadDir(stateDir)
	if err != nil {
		return nil
	}

	var reports []CheckoutSyncReport
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		// Checkout sync transactions: <feature>-checkout-sync.yaml
		if !strings.HasSuffix(name, "-checkout-sync.yaml") {
			continue
		}
		feature := strings.TrimSuffix(name, "-checkout-sync.yaml")
		txPath := filepath.Join(stateDir, name)
		report := buildOneSyncReport(feature, txPath, stateDir, proc)
		reports = append(reports, report)
	}
	return reports
}

func buildOneSyncReport(feature, txPath, stateDir string, proc ProcessChecker) CheckoutSyncReport {
	r := CheckoutSyncReport{
		Feature:  feature,
		Severity: SeverityOK,
	}

	data, err := os.ReadFile(txPath)
	if err != nil {
		r.Liveness = "invalid"
		r.Severity = SeverityError
		r.Guidance = "state file unreadable; manually remove " + txPath
		return r
	}

	var tx CheckoutTransaction
	if err := yaml.Unmarshal(data, &tx); err != nil {
		r.Liveness = "invalid"
		r.Severity = SeverityError
		r.Guidance = "corrupt transaction state; manually remove " + txPath
		return r
	}

	r.Stage = string(tx.Stage)
	// Derive current branch from plan if available
	if tx.CurrentIndex >= 0 && tx.CurrentIndex < len(tx.Plan) {
		r.CurrentBranch = tx.Plan[tx.CurrentIndex].Branch
	}
	if tx.FailureMsg != "" {
		r.FailureReason = tx.FailureMsg
	} else if tx.FailureKind != "" {
		r.FailureReason = string(tx.FailureKind)
	}
	r.LockPID = tx.LockPID

	// Check lock file
	lockName := feature + "-checkout-sync.lock"
	lockPath := filepath.Join(stateDir, lockName)
	lockData, lockErr := os.ReadFile(lockPath)
	if lockErr != nil {
		// Transaction exists but no lock — stale
		r.Liveness = "stale"
		r.LockLive = false
		r.Severity = SeverityWarning
		r.Guidance = fmt.Sprintf("stale sync transaction; run: tws sync %s --abort", feature)
		return r
	}

	var lock LockInfo
	if yaml.Unmarshal(lockData, &lock) != nil || lock.PID <= 0 {
		r.Liveness = "invalid"
		r.Severity = SeverityError
		r.Guidance = "corrupt lock file; manually remove " + lockPath
		return r
	}

	r.LockPID = lock.PID
	if proc.Alive(lock.PID) {
		r.LockLive = true
		r.Liveness = "live"
		r.Severity = SeverityInfo
	} else {
		r.LockLive = false
		r.Liveness = "stale"
		r.Severity = SeverityWarning
		if tx.FailureMsg != "" {
			r.Guidance = fmt.Sprintf("sync failed (%s) at stage %s; run: tws sync %s --continue  or  tws sync %s --abort", tx.FailureMsg, tx.Stage, feature, feature)
		} else {
			r.Guidance = fmt.Sprintf("stale sync lock (pid %d dead) at stage %s; run: tws sync %s --continue  or  tws sync %s --abort", lock.PID, tx.Stage, feature, feature)
		}
	}
	return r
}

// ---------- Session ----------

func buildSessionReport(ws Workspace, proc ProcessChecker, tmux TmuxChecker) *CheckoutSessionReport {
	r := &CheckoutSessionReport{Severity: SeverityOK}

	state, err := LoadCheckoutAgentSession(ws)
	if err != nil {
		// No active session state
		// Check for orphan lock
		if _, lockErr := os.Stat(sessionLockDir(ws)); lockErr == nil {
			r.LockHeld = true
			r.Liveness = "mismatch"
			r.Severity = SeverityWarning
			r.Guidance = "session lock exists but no session state; run: tws close"
			return r
		}
		return nil
	}

	r.Active = true
	r.Feature = state.Feature
	r.Name = state.Name
	r.Mode = state.Mode
	r.PID = state.PID
	r.TmuxSession = state.TmuxSession

	// Check lock
	_, lockErr := os.Stat(sessionLockDir(ws))
	r.LockHeld = lockErr == nil

	// Check liveness
	switch state.Mode {
	case AgentSessionDirect:
		if proc.Alive(state.PID) {
			r.OwnerLive = true
			r.Liveness = "live"
			r.Severity = SeverityInfo
		} else {
			r.OwnerLive = false
			r.Liveness = "stale"
			r.Severity = SeverityWarning
			r.Guidance = fmt.Sprintf("session owner pid %d is dead; run: tws close", state.PID)
		}
	case AgentSessionTmux:
		if state.TmuxSession != "" && tmux.HasSession(state.TmuxSession) {
			r.OwnerLive = true
			r.Liveness = "live"
			r.Severity = SeverityInfo
		} else {
			r.OwnerLive = false
			r.Liveness = "stale"
			r.Severity = SeverityWarning
			r.Guidance = fmt.Sprintf("tmux session %q is gone; run: tws close", state.TmuxSession)
		}
	}

	// Check state/lock mismatch
	if r.Active && !r.LockHeld {
		r.Liveness = "mismatch"
		r.Severity = SeverityWarning
		r.Guidance = "session state exists but lock is missing; run: tws close"
	} else if !r.Active && r.LockHeld {
		r.Liveness = "mismatch"
		r.Severity = SeverityWarning
		r.Guidance = "session lock exists but no session state; run: tws close"
	}

	return r
}

// ---------- Features ----------

func buildFeatureEntries(ws Workspace) ([]CheckoutFeatureEntry, error) {
	features, err := ws.ListFeaturesResolved()
	if err != nil {
		return nil, err
	}

	// Also load session to mark current
	var sessionFeature, sessionName string
	if sess, sErr := LoadCheckoutAgentSession(ws); sErr == nil {
		sessionFeature = sess.Feature
		sessionName = sess.Name
	}

	// Current branch for "current" detection
	currentBranch, _ := healthCurrentBranch(ws.RepoRoot)

	// Deliberately guard-free: features came from ListFeaturesResolved, which
	// already excluded space-owned names and failed closed on untrusted
	// spaces.yaml, so this continue cannot mask a spaces failure.
	var entries []CheckoutFeatureEntry
	for _, feature := range features {
		fp, resolveErr := ws.ResolveFeaturePath(feature)
		if resolveErr != nil {
			continue
		}
		stack, sErr := LoadStack(fp)
		if sErr != nil {
			continue
		}
		for _, se := range stack.Branches {
			entry := buildOneFeatureEntry(ws, feature, se, stack, currentBranch, sessionFeature, sessionName)
			entries = append(entries, entry)
		}
	}
	return entries, nil
}

func buildOneFeatureEntry(ws Workspace, feature string, se StackEntry, stack Stack, currentBranch, sessionFeature, sessionName string) CheckoutFeatureEntry {
	gitBranch := se.GitBranch()
	e := CheckoutFeatureEntry{
		Feature:   feature,
		Name:      se.Name,
		GitBranch: gitBranch,
		Archived:  se.Archived,
		Severity:  SeverityOK,
	}

	// Ref exists
	e.RefExists = gitRefExists(ws.RepoRoot, gitBranch)

	// Current — branch matches what's checked out
	e.Current = currentBranch == gitBranch

	// Session current
	if sessionFeature == feature && sessionName == se.Name {
		e.Current = true
	}

	// Base resolution — find parent entry or use literal ref
	baseGitBranch := se.Base
	isParentEntry := false
	for _, parent := range stack.Branches {
		if parent.Name == se.Base {
			baseGitBranch = parent.GitBranch()
			isParentEntry = true
			break
		}
	}
	e.BaseName = se.Base
	e.BaseGitBranch = baseGitBranch

	// Cross-repo check
	if se.Repo != "" {
		e.AncestryStatus = AncestryStatusCrossRepo
		e.Severity = SeverityInfo
		return e
	}

	// Ancestry classification
	if !e.RefExists {
		e.AncestryStatus = AncestryStatusMissing
		e.Severity = SeverityWarning
		return e
	}

	if !gitRefExists(ws.RepoRoot, baseGitBranch) {
		e.AncestryStatus = AncestryStatusMissing
		e.Severity = SeverityWarning
		return e
	}

	// Get heads for display
	e.LocalHead = gitShortSHA(ws.RepoRoot, gitBranch)
	if isParentEntry {
		e.ParentHead = gitShortSHA(ws.RepoRoot, baseGitBranch)
	} else {
		e.ParentHead = gitShortSHA(ws.RepoRoot, baseGitBranch)
	}

	// merge-base check
	mb, mbErr := gitMergeBase(ws.RepoRoot, gitBranch, baseGitBranch)
	if mbErr != nil {
		e.AncestryStatus = AncestryStatusMissing
		e.Severity = SeverityWarning
		return e
	}

	baseHead := gitFullSHA(ws.RepoRoot, baseGitBranch)
	if mb == baseHead {
		e.AncestryStatus = AncestryStatusCurrent
	} else if childBehind, _ := gitIsAncestor(ws.RepoRoot, gitBranch, baseGitBranch); childBehind {
		e.AncestryStatus = AncestryStatusStale
		e.Severity = SeverityWarning
	} else {
		e.AncestryStatus = AncestryStatusDivergent
		e.Severity = SeverityWarning
	}

	return e
}

func gitRefExists(repo, ref string) bool {
	return exec.Command("git", "-C", repo, "rev-parse", "--verify", "--quiet", ref).Run() == nil
}

func gitShortSHA(repo, ref string) string {
	out, err := exec.Command("git", "-C", repo, "rev-parse", "--short", ref).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func gitFullSHA(repo, ref string) string {
	out, err := exec.Command("git", "-C", repo, "rev-parse", ref).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func gitMergeBase(repo, a, b string) (string, error) {
	out, err := exec.Command("git", "-C", repo, "merge-base", a, b).Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

// ---------- Context Links ----------

func buildContextLinks(ws Workspace) []CheckoutContextLinkReport {
	state, err := LoadCheckoutAgentSession(ws)
	if err != nil || len(state.Links) == 0 {
		return nil
	}

	var reports []CheckoutContextLinkReport
	for _, link := range state.Links {
		r := inspectContextLink(link)
		reports = append(reports, r)
	}
	return reports
}

func inspectContextLink(link SessionContextLink) CheckoutContextLinkReport {
	r := CheckoutContextLinkReport{
		Path:     link.Path,
		Target:   link.Target,
		Severity: SeverityOK,
	}

	info, err := os.Lstat(link.Path)
	if err != nil {
		r.Status = "missing"
		r.Severity = SeverityWarning
		return r
	}

	if info.Mode()&os.ModeSymlink == 0 {
		r.Status = "not-symlink"
		r.Severity = SeverityWarning
		return r
	}

	actual, readErr := os.Readlink(link.Path)
	if readErr != nil {
		r.Status = "missing"
		r.Severity = SeverityWarning
		return r
	}

	if actual != link.Target {
		r.Status = "replaced"
		r.Severity = SeverityWarning
		return r
	}

	r.Status = "healthy"
	return r
}

// ---------- Issue counting ----------

func countIssues(r *CheckoutHealthReport) int {
	n := 0
	if r.Header.Dirty {
		n++
	}
	if r.Header.ActiveGitOp != "" {
		n++
	}
	for _, s := range r.Sync {
		if s.Severity == SeverityWarning || s.Severity == SeverityError {
			n++
		}
	}
	if r.Session != nil && (r.Session.Severity == SeverityWarning || r.Session.Severity == SeverityError) {
		n++
	}
	for _, f := range r.Features {
		if f.Severity == SeverityWarning || f.Severity == SeverityError {
			n++
		}
	}
	for _, l := range r.Links {
		if l.Severity == SeverityWarning || l.Severity == SeverityError {
			n++
		}
	}
	return n
}

// ---------- Formatted output ----------

// FormatCheckoutHealth produces concise human-readable output.
func FormatCheckoutHealth(r *CheckoutHealthReport) string {
	var b strings.Builder

	// Header
	fmt.Fprintf(&b, "Workspace: %s (mode: %s)\n", r.Header.Metadata, r.Header.Mode)
	fmt.Fprintf(&b, "  ID:   %s\n", r.Header.StableID)
	fmt.Fprintf(&b, "  Repo: %s\n", r.Header.RepoRoot)
	if r.Header.Detached {
		fmt.Fprintf(&b, "  HEAD: %s (detached)\n", r.Header.Branch)
	} else {
		fmt.Fprintf(&b, "  Branch: %s\n", r.Header.Branch)
	}
	if r.Header.Dirty {
		b.WriteString("  [!] Working tree is dirty\n")
	}
	if r.Header.ActiveGitOp != "" {
		fmt.Fprintf(&b, "  [!] Active Git operation: %s\n", r.Header.ActiveGitOp)
	}

	// Sync
	if len(r.Sync) > 0 {
		b.WriteString("\nSync:\n")
		for _, s := range r.Sync {
			icon := severityIcon(s.Severity)
			fmt.Fprintf(&b, "  %s %s: stage=%s liveness=%s", icon, s.Feature, s.Stage, s.Liveness)
			if s.FailureReason != "" {
				fmt.Fprintf(&b, " failure=%s", s.FailureReason)
			}
			if s.LockPID > 0 {
				fmt.Fprintf(&b, " lock-pid=%d", s.LockPID)
			}
			b.WriteString("\n")
			if s.Guidance != "" {
				fmt.Fprintf(&b, "      %s\n", s.Guidance)
			}
		}
	}

	// Session
	if r.Session != nil {
		b.WriteString("\nSession:\n")
		if !r.Session.Active && r.Session.LockHeld {
			fmt.Fprintf(&b, "  [!] orphan lock — %s\n", r.Session.Guidance)
		} else if r.Session.Active {
			icon := severityIcon(r.Session.Severity)
			fmt.Fprintf(&b, "  %s %s/%s mode=%s liveness=%s", icon, r.Session.Feature, r.Session.Name, r.Session.Mode, r.Session.Liveness)
			if r.Session.PID > 0 {
				fmt.Fprintf(&b, " pid=%d", r.Session.PID)
			}
			if r.Session.TmuxSession != "" {
				fmt.Fprintf(&b, " tmux=%s", r.Session.TmuxSession)
			}
			b.WriteString("\n")
			if r.Session.Guidance != "" {
				fmt.Fprintf(&b, "      %s\n", r.Session.Guidance)
			}
		}
	}

	// Features
	if len(r.Features) > 0 {
		b.WriteString("\nFeatures:\n")
		for _, f := range r.Features {
			icon := severityIcon(f.Severity)
			tags := ""
			if f.Archived {
				tags += " [archived]"
			}
			if f.Current {
				tags += " [current]"
			}
			if !f.RefExists {
				tags += " [ref-missing]"
			}
			fmt.Fprintf(&b, "  %s %s/%s", icon, f.Feature, f.Name)
			if f.GitBranch != f.Name {
				fmt.Fprintf(&b, " (git: %s)", f.GitBranch)
			}
			fmt.Fprintf(&b, " base=%s ancestry=%s%s", f.BaseName, f.AncestryStatus, tags)
			if f.LocalHead != "" {
				fmt.Fprintf(&b, " head=%s", f.LocalHead)
			}
			if f.ParentHead != "" {
				fmt.Fprintf(&b, " parent=%s", f.ParentHead)
			}
			b.WriteString("\n")
		}
	}

	// Context links
	if len(r.Links) > 0 {
		b.WriteString("\nContext Links:\n")
		for _, l := range r.Links {
			icon := severityIcon(l.Severity)
			fmt.Fprintf(&b, "  %s %s -> %s [%s]\n", icon, l.Path, l.Target, l.Status)
		}
	}

	// Summary
	if r.Issues == 0 {
		b.WriteString("\nAll healthy.\n")
	} else {
		fmt.Fprintf(&b, "\n%d issue(s) found.\n", r.Issues)
	}

	return b.String()
}

func severityIcon(s CheckoutSeverity) string {
	switch s {
	case SeverityOK:
		return "[ok]"
	case SeverityInfo:
		return "[i]"
	case SeverityWarning:
		return "[!]"
	case SeverityError:
		return "[E]"
	default:
		return "[ ]"
	}
}

// ---------- Checkout list helpers ----------

// CheckoutListEntry represents one entry for the checkout list view.
type CheckoutListEntry struct {
	Feature        string `json:"feature"`
	Name           string `json:"name"`
	GitBranch      string `json:"git_branch"`
	Current        bool   `json:"current"`
	Archived       bool   `json:"archived"`
	AncestryStatus string `json:"ancestry_status"`
	SessionActive  bool   `json:"session_active"`
}

// BuildCheckoutList builds the checkout list view entries.
func BuildCheckoutList(ws Workspace) ([]CheckoutListEntry, error) {
	features, err := ws.ListFeaturesResolved()
	if err != nil {
		return nil, err
	}

	currentBranch, _ := healthCurrentBranch(ws.RepoRoot)

	var sessionFeature, sessionName string
	if sess, sErr := LoadCheckoutAgentSession(ws); sErr == nil {
		sessionFeature = sess.Feature
		sessionName = sess.Name
	}

	// Deliberately guard-free, for the same reason as buildFeatureEntries.
	var entries []CheckoutListEntry
	for _, feature := range features {
		fp, resolveErr := ws.ResolveFeaturePath(feature)
		if resolveErr != nil {
			continue
		}
		stack, sErr := LoadStack(fp)
		if sErr != nil {
			continue
		}
		for _, se := range stack.Branches {
			gitBranch := se.GitBranch()
			e := CheckoutListEntry{
				Feature:   feature,
				Name:      se.Name,
				GitBranch: gitBranch,
				Current:   currentBranch == gitBranch || (sessionFeature == feature && sessionName == se.Name),
				Archived:  se.Archived,
			}

			// Ancestry
			if se.Repo != "" {
				e.AncestryStatus = string(AncestryStatusCrossRepo)
			} else if !gitRefExists(ws.RepoRoot, gitBranch) {
				e.AncestryStatus = string(AncestryStatusMissing)
			} else {
				baseRef := se.Base
				for _, parent := range stack.Branches {
					if parent.Name == se.Base {
						baseRef = parent.GitBranch()
						break
					}
				}
				if !gitRefExists(ws.RepoRoot, baseRef) {
					e.AncestryStatus = string(AncestryStatusMissing)
				} else if mb, mbErr := gitMergeBase(ws.RepoRoot, gitBranch, baseRef); mbErr != nil {
					e.AncestryStatus = string(AncestryStatusMissing)
				} else if mb == gitFullSHA(ws.RepoRoot, baseRef) {
					e.AncestryStatus = string(AncestryStatusCurrent)
				} else {
					e.AncestryStatus = string(AncestryStatusStale)
				}
			}

			// Session
			if sessionFeature == feature && sessionName == se.Name {
				e.SessionActive = true
			}

			entries = append(entries, e)
		}
	}
	return entries, nil
}

// FormatCheckoutList formats the checkout list for display.
func FormatCheckoutList(ws Workspace, entries []CheckoutListEntry) string {
	var b strings.Builder

	fmt.Fprintf(&b, "Workspace: %s (mode: %s)\n\n", ws.MetadataRoot, ws.Mode)

	if len(entries) == 0 {
		b.WriteString("No features found. Use 'tws add <feature>' to create one.\n")
		return b.String()
	}

	// Group by feature
	featureEntries := make(map[string][]CheckoutListEntry)
	var featureOrder []string
	for _, e := range entries {
		if _, ok := featureEntries[e.Feature]; !ok {
			featureOrder = append(featureOrder, e.Feature)
		}
		featureEntries[e.Feature] = append(featureEntries[e.Feature], e)
	}
	for _, feature := range featureOrder {
		fEntries := featureEntries[feature]
		fmt.Fprintf(&b, "%s\n", feature)
		for i, e := range fEntries {
			connector := "├──"
			if i == len(fEntries)-1 {
				connector = "└──"
			}

			// Branch display
			branchDisplay := e.Name
			if e.GitBranch != e.Name {
				branchDisplay += fmt.Sprintf(" (git: %s)", e.GitBranch)
			}

			tags := ""
			if e.Current {
				tags += " *"
			}
			if e.Archived {
				tags += " [archived]"
			}
			if e.AncestryStatus != "" && e.AncestryStatus != string(AncestryStatusCurrent) {
				tags += fmt.Sprintf(" [%s]", e.AncestryStatus)
			}
			if e.SessionActive {
				tags += " [session]"
			}

			fmt.Fprintf(&b, "  %s %s%s\n", connector, branchDisplay, tags)
		}
		b.WriteString("\n")
	}

	return b.String()
}

package cli

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	skills "github.com/jdbencardinop/tesseraworkspaces/assets/skills"
	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func addCmd() *cobra.Command {
	var templates []string
	var newBranch string
	var base string
	var open bool
	var force bool
	var useTmux bool

	cmd := &cobra.Command{
		Use:   "add <feature>",
		Short: "Create a feature workspace",
		Long: `Create a feature workspace with an inject/ directory for shared files.

Files in inject/ are symlinked into every worktree. Use -n to also
create a first worktree branch, and --open to launch the agent.

Note: injected files appear as untracked in git status. Add them to
.gitignore or place them in an already-ignored subfolder.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return addCheckout(ws, feature, templates, newBranch, base, force, open, useTmux)
			}
			return addExternal(feature, templates, newBranch, base, force, open, useTmux)
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory to copy into inject/ (can be specified multiple times)")
	cmd.Flags().StringVarP(&newBranch, "new", "n", "", "Also create a worktree branch")
	cmd.Flags().StringVar(&base, "base", "", "Base branch for the new worktree (default: repo's default branch)")
	cmd.Flags().BoolVar(&open, "open", false, "Open the worktree after creation (used with -n)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Open in tmux session (used with --open)")

	return cmd
}

// addExternal preserves existing external-mode add semantics.
func addExternal(feature string, templates []string, newBranch, base string, force, open, useTmux bool) error {
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	root := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Join(root, "worktrees"), 0755); err != nil {
		return fmt.Errorf("creating worktrees directory: %w", err)
	}
	if err := os.WriteFile(filepath.Join(root, "FEATURE.md"), []byte("# "+feature+"\n"), 0644); err != nil {
		return fmt.Errorf("creating FEATURE.md: %w", err)
	}

	injectDir := internal.InjectPath(root)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}

	applyTemplates(injectDir, templates)

	claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
	if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
		if err := os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is symlinked into every worktree for this feature.\nEdit it in the workspace inject/ directory.\n"), 0644); err != nil {
			return fmt.Errorf("creating CLAUDE.local.md: %w", err)
		}
	}

	orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
	installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

	fmt.Println("Feature added:", feature)

	if newBranch != "" {
		if err := createWorktree(feature, newBranch, base, "", force); err != nil {
			return err
		}
		if open {
			path := internal.WorktreePath(feature, newBranch)
			if useTmux {
				openWithTmux(feature, newBranch, path)
			} else {
				if err := openDirect(directOpenOpts{
					Path:        path,
					Feature:     feature,
					Name:        newBranch,
					GitBranch:   resolveDirectGitBranch(root, newBranch),
					FeaturePath: root,
				}); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// addCheckout creates durable feature assets under .tws/features/<feature>
// for checkout mode. Idempotent: re-running on an existing feature updates
// only missing assets.
func addCheckout(ws internal.Workspace, feature string, templates []string, newBranch, base string, force, open, useTmux bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	root := ws.FeaturePath(feature)

	// Create the feature directory (no worktrees/ subdirectory in checkout mode).
	if err := os.MkdirAll(root, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(root, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		if err := os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644); err != nil {
			return fmt.Errorf("creating FEATURE.md: %w", err)
		}
	}

	// inject/ directory
	injectDir := internal.InjectPath(root)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}

	applyTemplates(injectDir, templates)

	// Default CLAUDE.local.md if no template provided one
	claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
	if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
		if err := os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is maintained in the checkout workspace.\n"), 0644); err != nil {
			return fmt.Errorf("creating CLAUDE.local.md: %w", err)
		}
	}

	// Orchestrator skill in feature .claude/skills/
	orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
	installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

	fmt.Println("Feature added:", feature)

	// In checkout mode, -n creates a branch (not a worktree).
	if newBranch != "" {
		if err := createCheckoutBranch(ws, feature, newBranch, base, force); err != nil {
			return err
		}
		if open {
			// In checkout mode, "open" switches to branch in the repo root.
			if useTmux {
				openCheckoutTmux(ws, feature, newBranch)
			} else {
				fmt.Printf("Branch %s created. Use 'git checkout %s' to switch.\n", newBranch, newBranch)
			}
		}
	}
	return nil
}

// applyTemplates copies files from the configured template dir and any
// explicit --template dirs into the inject directory.
func applyTemplates(injectDir string, extraTemplates []string) {
	// Configured default template first
	defaultTemplate := internal.TemplatePath()
	if defaultTemplate != "" {
		count, err := copyDir(defaultTemplate, injectDir)
		if err != nil {
			fmt.Printf("Warning: default template copy failed: %v\n", err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from default template\n", count)
		}
	}

	// Then explicit --template dirs (layered in order)
	for _, tmplDir := range extraTemplates {
		info, err := os.Stat(tmplDir)
		if err != nil || !info.IsDir() {
			fmt.Printf("Warning: template directory not found: %s\n", tmplDir)
			continue
		}
		count, err := copyDir(tmplDir, injectDir)
		if err != nil {
			fmt.Printf("Warning: template copy failed for %s: %v\n", tmplDir, err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from %s\n", count, tmplDir)
		}
	}
}

// copyDir copies all files from src to dst, preserving directory structure.
// Does not overwrite existing files. Returns the count of files copied.
func copyDir(src, dst string) (int, error) {
	count := 0
	err := filepath.Walk(src, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, srcPath)
		if err != nil {
			return err
		}
		if relPath == "." {
			return nil
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, 0755)
		}

		// Skip if exists (conflict resolution is a separate feature)
		if _, err := os.Stat(dstPath); err == nil {
			fmt.Printf("  skip: %s (exists)\n", relPath)
			return nil
		}

		// Copy file
		in, err := os.Open(srcPath)
		if err != nil {
			return err
		}
		defer in.Close() //nolint:errcheck

		out, err := os.Create(dstPath)
		if err != nil {
			return err
		}
		defer out.Close() //nolint:errcheck

		if _, err := io.Copy(out, in); err != nil {
			return err
		}
		count++
		return nil
	})
	return count, err
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func archiveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "archive <feature> <branch>",
		Short: "Remove worktree from disk, keep branch and metadata",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			branch := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return archiveCheckout(ws, feature, branch)
			}
			return archiveExternal(feature, branch)
		},
	}
}

// archiveCheckout marks a branch as archived in metadata only.
// The git branch is preserved; no worktree to remove.
func archiveCheckout(ws internal.Workspace, feature, branch string) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	found := false
	for i := range stack.Branches {
		if stack.Branches[i].Name == branch {
			if stack.Branches[i].Archived {
				fmt.Printf("Branch %s is already archived\n", branch)
				return nil
			}
			stack.Branches[i].Archived = true
			found = true
			break
		}
	}
	if !found {
		return fmt.Errorf("branch %q not found in stack for feature %s", branch, feature)
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}

	fmt.Printf("Archived branch: %s (git branch preserved)\n", branch)
	return nil
}

// archiveExternal removes the worktree from disk but preserves the git branch.
func archiveExternal(feature, branch string) error {
	if err := internal.GuardFeatureName(internal.TwsRoot(), feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, branch)

	// Archiving removes the worktree a live session's path points at, i.e.
	// the agent's own working directory. The guard precedes the
	// worktree-absent branch below, which also mutates stack.yaml.
	if gerr := guardDirectRecords(os.Stdout, featurePath, "archive", feature+"/"+branch,
		directRecordTargetForBranch(feature, branch)); gerr != nil {
		return gerr
	}

	if _, err := os.Stat(path); os.IsNotExist(err) {
		// Mark as archived in stack if not already.
		stack, loadErr := internal.LoadStack(featurePath)
		if loadErr == nil {
			for i := range stack.Branches {
				if stack.Branches[i].Name == branch {
					stack.Branches[i].Archived = true
					break
				}
			}
			_ = internal.SaveStack(featurePath, stack)
		}
		fmt.Printf("Worktree already removed: %s\n", path)
		return nil
	}

	// Use git worktree remove to cleanly detach.
	if err := internal.Run("git", "worktree", "remove", "--force", path); err != nil {
		return fmt.Errorf("error removing worktree: %w", err)
	}

	// Mark as archived in stack.
	stack, loadErr := internal.LoadStack(featurePath)
	if loadErr == nil {
		for i := range stack.Branches {
			if stack.Branches[i].Name == branch {
				stack.Branches[i].Archived = true
				break
			}
		}
		_ = internal.SaveStack(featurePath, stack)
	}

	// Kill tmux session if running.
	session := sanitizeSessionName(feature + "/" + branch)
	if sessionExists(session) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", session)
	}

	fmt.Printf("Archived worktree: %s → %s (branch preserved)\n", feature, branch)
	return nil
}

package cli

import (
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func closeCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "close [feature] [branch]",
		Short: "Close a worktree session (tmux or checkout)",
		Args:  cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			ws, err := internal.RequireWorkspace()
			if err == nil && ws.Mode == internal.ModeCheckout {
				state, loadErr := internal.LoadCheckoutAgentSession(ws)
				if loadErr != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				if len(args) == 0 {
					return []string{state.Feature}, cobra.ShellCompDirectiveNoFileComp
				}
				if len(args) == 1 && args[0] == state.Feature {
					return []string{state.Name}, cobra.ShellCompDirectiveNoFileComp
				}
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		// The external branch resolves a caller-supplied feature name to a
		// path under TwsRoot() and mutates files beneath it (direct session
		// records), so it is guarded like every other external path-joining
		// command. The checkout branch still resolves its identity from
		// active.json rather than from a caller-supplied name and needs no
		// guard.
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			// Checkout mode: delegate to checkout close
			if ws.Mode == internal.ModeCheckout {
				if cerr := runCheckoutClose(ws, args); cerr != nil {
					return cerr
				}
				fmt.Println("Checkout session closed.")
				return nil
			}

			// External mode: requires exactly 2 args
			if len(args) != 2 {
				return fmt.Errorf("usage: tws close <feature> <branch>")
			}

			feature := args[0]
			branch := args[1]

			// Guard first: the refusal must be the first observable action,
			// before any path is computed, statted, read, or removed, and
			// before the tmux name is built.
			if gerr := internal.GuardFeatureName(internal.TwsRoot(), feature); gerr != nil {
				return gerr
			}

			return runExternalClose(cmd.OutOrStdout(), feature, branch, nil, realExternalTmuxOps{})
		},
	}
}

// externalTmuxOps is the tmux seam of the external close path.
type externalTmuxOps interface {
	Exists(name string) bool
	Kill(name string) error
}

type realExternalTmuxOps struct{}

func (realExternalTmuxOps) Exists(name string) bool { return sessionExists(name) }
func (realExternalTmuxOps) Kill(name string) error {
	return internal.Run("tmux", "kill-session", "-t", name)
}

// runExternalClose implements the external close ordering: records are
// consulted before tmux, because refusing to disturb a live direct session
// outranks killing a tmux session.
//
// Three record classes exist and each is handled differently:
//
//	live         — refuse; kill nothing, remove nothing.
//	stale        — provably dead; removed by token, one file at a time.
//	unverifiable — State != ok, or Probe == unknown (EPERM). Never removed and
//	               never blocking, but always reported: silently dropping them
//	               would make a close that changed nothing look like a close
//	               that cleaned up.
func runExternalClose(out io.Writer, feature, branch string, proc internal.ProcessProber, tmux externalTmuxOps) error {
	if proc == nil {
		proc = internal.NewProcessProber()
	}
	featurePath := internal.FeaturePath(feature)
	branchID := internal.DirectSessionBranchID(feature, branch)
	records, err := internal.LoadDirectSessions(featurePath, branchID,
		&internal.DirectSessionIdentity{Feature: feature, Name: branch})
	if err != nil {
		return err
	}

	var live, stale, unverifiable []internal.LoadedDirectSession
	for _, rec := range records {
		if rec.State != internal.DirectRecordOK {
			// Not provably stale: never counted live, never removed, and it
			// does not by itself block the tmux kill.
			unverifiable = append(unverifiable, rec)
			continue
		}
		switch proc.Probe(rec.Record.OwnerPID) {
		case internal.ProcessLive:
			live = append(live, rec)
		case internal.ProcessDead:
			stale = append(stale, rec)
		default:
			// EPERM: the pid exists but belongs to another user, so it is not
			// provably dead and must not be removed.
			unverifiable = append(unverifiable, rec)
		}
	}

	if len(live) > 0 {
		var b strings.Builder
		fmt.Fprintf(&b, "%s/%s has %d live direct session record(s); tws never kills a direct process",
			feature, branch, len(live))
		for _, rec := range live {
			fmt.Fprintf(&b, "\n  %s", internal.DescribeDirectSession(rec))
		}
		b.WriteString("\nexit the session, then run tws close again")
		return errors.New(b.String())
	}

	removed := 0
	if len(stale) > 0 {
		n, remErr := internal.RemoveStaleDirectSessions(featurePath, stale)
		removed = n
		if remErr != nil {
			_, _ = fmt.Fprintf(out, "Warning: could not remove every stale record: %v\n", remErr)
		}
	}

	// Reported before tmux is touched, so the operator reads what was left
	// behind before reading what was killed. DescribeDirectSession renders the
	// record path and ownership token redacted.
	if len(unverifiable) > 0 {
		_, _ = fmt.Fprintf(out, "%d direct session record(s) for %s/%s could not be verified and were left in place:\n",
			len(unverifiable), feature, branch)
		for _, rec := range unverifiable {
			_, _ = fmt.Fprintf(out, "  %s\n", internal.DescribeDirectSession(rec))
		}
	}

	session := internal.ExternalTmuxSessionName(feature, branch)
	if tmux.Exists(session) {
		if err := tmux.Kill(session); err != nil {
			return fmt.Errorf("error killing session: %w", err)
		}
		if removed > 0 {
			_, _ = fmt.Fprintf(out, "Removed %d stale direct session record(s) for %s/%s.\n", removed, feature, branch)
		}
		_, _ = fmt.Fprintf(out, "Closed tmux session: %s\n", session)
		return nil
	}

	if removed > 0 {
		_, _ = fmt.Fprintf(out, "Removed %d stale direct session record(s) for %s/%s.\n", removed, feature, branch)
		return nil
	}
	if len(unverifiable) > 0 {
		// The flat "no tmux" error would be a false negative here: close did
		// find state for this branch, it just could not act on any of it.
		return fmt.Errorf("no tmux session found for %s/%s, and %d direct session record(s) could not be verified, so nothing was removed; inspect them with: tws status --json",
			feature, branch, len(unverifiable))
	}
	return fmt.Errorf("no tmux session found for %s/%s", feature, branch)
}

// TmuxSessionName returns the tmux session name for a feature/branch pair.
func TmuxSessionName(feature, branch string) string {
	return internal.ExternalTmuxSessionName(feature, branch)
}

