// ---------- real process lifecycle ----------

// TestRealDirectProcessTerminateThenWait drives the real implementation, not a
// fake: Terminate only signals, the caller reaps with Wait, and Wait is
// idempotent so no second exec.Cmd.Wait can panic.
func TestRealDirectProcessTerminateThenWait(t *testing.T) {
	proc, err := realDirectRunner{}.Start(t.TempDir(), []string{"/bin/sh", "-c", "sleep 30"})
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	if proc.PID() <= 0 {
		t.Fatalf("pid = %d", proc.PID())
	}
	if err := proc.Terminate(); err != nil {
		t.Fatalf("Terminate: %v", err)
	}

	done := make(chan error, 1)
	go func() { done <- proc.Wait() }()
	select {
	case <-done:
		// A SIGTERM-ed child exits non-zero; the exit status is the caller's
		// business, the reaping is what matters here.
	case <-time.After(10 * time.Second):
		t.Fatal("Wait never returned after Terminate")
	}

	// Idempotent: the escalation goroutine is already released, and a second
	// Wait must neither block nor reach exec.Cmd.Wait twice.
	second := make(chan error, 1)
	go func() { second <- proc.Wait() }()
	select {
	case <-second:
	case <-time.After(5 * time.Second):
		t.Fatal("a second Wait must return immediately")
	}
}

// TestRealDirectProcessWaitReleasesEscalation asserts the SIGKILL escalation
// cannot outlive a successful Wait: a process that exits on its own is reaped,
// and the pending kill goroutine observes the done channel instead of signalling
// a pid the OS may have recycled.
func TestRealDirectProcessWaitReleasesEscalation(t *testing.T) {
	proc, err := realDirectRunner{}.Start(t.TempDir(), []string{"/bin/sh", "-c", "exit 0"})
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	real, ok := proc.(*realDirectProcess)
	if !ok {
		t.Fatalf("runner returned %T", proc)
	}
	if err := real.Terminate(); err != nil {
		t.Fatalf("Terminate: %v", err)
	}
	_ = real.Wait()
	select {
	case <-real.done:
	default:
		t.Fatal("Wait must close the done channel so the escalation is released")
	}
}

package cli

import (
	"bytes"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// deadOwnerPID is a pid no test process owns, so a seeded record is classified
// provably stale by the real prober and would be removed by a close that got
// past the guard.
const deadOwnerPID = 99998

// fakeTmuxOnPath installs a tmux stub that records every invocation, and
// returns the log path. Its existence proves a command reached tmux; its
// absence proves the refusal preceded any tmux probe or kill.
func fakeTmuxOnPath(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	log := filepath.Join(dir, "tmux-invocations.log")
	script := "#!/bin/sh\necho \"$@\" >> " + log + "\nexit 0\n"
	if err := os.WriteFile(filepath.Join(dir, "tmux"), []byte(script), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	return log
}

func requireNoTmuxInvocation(t *testing.T, log string) {
	t.Helper()
	if data, err := os.ReadFile(log); err == nil {
		t.Fatalf("tmux was invoked before the refusal: %s", data)
	}
}

// outsideFeatureFixture plants a feature-shaped tree one level above the
// workspace root, holding one direct session record for
// (feature="../outside", branch="branch"). Any command that joins the
// caller-supplied name under the root reaches exactly this tree.
func outsideFeatureFixture(t *testing.T, root string) string {
	t.Helper()
	outside := mustMkdir(t, filepath.Join(filepath.Dir(root), "outside"))
	mustMkdir(t, filepath.Join(outside, "worktrees"))
	if err := os.WriteFile(filepath.Join(outside, "keep.md"), []byte("outside bytes\n"), 0644); err != nil {
		t.Fatal(err)
	}
	seedRecord(t, outside, "../outside", "branch", deadOwnerPID)
	return outside
}

// TestExternalCloseRefusesTraversalFeatureName pins that `tws close ../outside
// branch` is refused by the feature-name guard before any path under
// TwsRoot() is joined, so no record outside the workspace is read or removed
// and tmux is never touched.
func TestExternalCloseRefusesTraversalFeatureName(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)
	mustMkdir(t, root)
	tmuxLog := fakeTmuxOnPath(t)

	outside := outsideFeatureFixture(t, root)
	before := snapshotRecordTree(t, outside)

	cmd := closeCmd()
	cmd.SetArgs([]string{"../outside", "branch"})
	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&out)
	cmd.SilenceUsage = true

	err := cmd.Execute()
	if err == nil {
		t.Fatalf("close must refuse a traversing feature name (output: %s)", out.String())
	}
	if want := `feature name "../outside" contains path separator`; err.Error() != want {
		t.Fatalf("err = %v, want %q", err, want)
	}
	if after := snapshotRecordTree(t, outside); after != before {
		t.Fatalf("the tree outside the workspace changed:\n%s\n---\n%s", before, after)
	}
	requireNoTmuxInvocation(t, tmuxLog)

	// Negative control: the guard is what protects the outside tree. Calling
	// the guard-free internal close with the same name does reach it.
	proc := fakeCLIProber{probe: map[int]internal.ProcessLiveness{deadOwnerPID: internal.ProcessDead}}
	tmux := &fakeTmuxOps{exists: map[string]bool{}}
	var controlOut bytes.Buffer
	_ = runExternalClose(&controlOut, "../outside", "branch", proc, tmux)
	if after := snapshotRecordTree(t, outside); after == before {
		t.Fatal("the fixture proves nothing: an unguarded close left the outside record in place")
	}
}

// TestExternalCloseRefusesEveryUnsafeFeatureSpelling covers the other unsafe
// name classes the shared guard now rejects, each before any filesystem or
// tmux action.
func TestExternalCloseRefusesEveryUnsafeFeatureSpelling(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)
	mustMkdir(t, root)
	tmuxLog := fakeTmuxOnPath(t)
	outside := outsideFeatureFixture(t, root)
	before := snapshotRecordTree(t, outside)

	cases := map[string]string{
		"..":            `feature name ".." contains path traversal`,
		".":             `feature name "." is reserved`,
		"sub/feature":   `feature name "sub/feature" contains path separator`,
		"../../escape":  `feature name "../../escape" contains path separator`,
		".hidden":       `feature name ".hidden" conflicts with reserved directory`,
		"features":      `feature name "features" conflicts with reserved directory`,
		"spaces.yaml":   `feature name "spaces.yaml" conflicts with reserved directory`,
		"nested/../out": `feature name "nested/../out" contains path separator`,
	}
	for feature, want := range cases {
		t.Run(feature, func(t *testing.T) {
			cmd := closeCmd()
			cmd.SetArgs([]string{feature, "branch"})
			var out bytes.Buffer
			cmd.SetOut(&out)
			cmd.SetErr(&out)
			cmd.SilenceUsage = true
			err := cmd.Execute()
			if err == nil || err.Error() != want {
				t.Fatalf("close %q err = %v, want %q", feature, err, want)
			}
		})
	}

	if after := snapshotRecordTree(t, outside); after != before {
		t.Fatalf("the tree outside the workspace changed:\n%s\n---\n%s", before, after)
	}
	requireNoTmuxInvocation(t, tmuxLog)
	// Positive control: a legal feature name is not refused and still reaches
	// tmux, so the refusals above are the guard and not a broken fixture.
	cmd := closeCmd()
	cmd.SetArgs([]string{"acme", "branch"})
	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&out)
	cmd.SilenceUsage = true
	if err := cmd.Execute(); err != nil {
		t.Fatalf("a valid feature name must keep its behaviour, got %v", err)
	}
	data, err := os.ReadFile(tmuxLog)
	if err != nil || !strings.Contains(string(data), "has-session") {
		t.Fatalf("a valid feature name must reach tmux: %s (%v)", data, err)
	}
}

// TestStatusRefusesTraversalFeatureName pins the same refusal on the other
// surface this feature newly guards: `tws status` with a caller-supplied name.
func TestStatusRefusesTraversalFeatureName(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)
	mustMkdir(t, root)
	tmuxLog := fakeTmuxOnPath(t)
	outside := outsideFeatureFixture(t, root)
	before := snapshotRecordTree(t, outside)

	for _, feature := range []string{"../outside", "..", "sub/feature", "features"} {
		out, _, err := runStatus(t, feature)
		if err == nil {
			t.Fatalf("status %q must be refused (output: %s)", feature, out)
		}
		if !strings.Contains(err.Error(), "feature name "+strconv.Quote(feature)) {
			t.Fatalf("status %q err = %v", feature, err)
		}
		if out != "" {
			t.Fatalf("status %q printed a report before refusing: %s", feature, out)
		}
	}
	if _, _, err := runStatus(t, "--json", "../outside"); err == nil {
		t.Fatal("--json must be refused identically")
	}

	if after := snapshotRecordTree(t, outside); after != before {
		t.Fatalf("the tree outside the workspace changed:\n%s\n---\n%s", before, after)
	}
	requireNoTmuxInvocation(t, tmuxLog)
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.`,
		Args: cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					fmt.Printf("Opening feature dir: %s\n", fp)
					// Untracked: a feature directory is not a logical branch,
					// so no direct session record is created.
					return openDirect(directOpenOpts{Path: fp})
				}

				return runCheckoutOpen(ws, args, useTmux, noTmux, noAgent, cmd.Flags())
			}

			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				// Guarded because the feature name is joined under TwsRoot().
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
				openAll(args[0])
				return nil
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				// Guarded because the feature name is joined under TwsRoot().
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), feature); gerr != nil {
					return gerr
				}
				path := internal.FeaturePath(feature)
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				fmt.Printf("Opening feature dir: %s\n", path)
				// Untracked: see the checkout branch above.
				return openDirect(directOpenOpts{Path: path})
			}

			// Normal mode: open a specific worktree
			if len(args) >= 1 {
				// The 0-arg picker is covered by ListFeaturesE inside
				// resolveOpenArgs.
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
			}
			feature, branch, err := resolveOpenArgs(args)
			if err != nil {
				return err
			}

			path := internal.WorktreePath(feature, branch)

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			featurePath := internal.FeaturePath(feature)
			injectTarget := internal.ResolveInjectInto("")
			if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				openWithTmux(feature, branch, path)
			} else {
				// Warn if there's a stale tmux session
				session := sanitizeSessionName(feature + "/" + branch)
				if sessionExists(session) {
					fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
					fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
				}
				return openDirect(directOpenOpts{
					Path:        path,
					Feature:     feature,
					Name:        branch,
					GitBranch:   resolveDirectGitBranch(featurePath, branch),
					FeaturePath: featurePath,
				})
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")

	return cmd
}

func resolveOpenArgs(args []string) (string, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		feature = args[0]
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	case 0:
		features, listErr := internal.ListFeaturesE()
		if listErr != nil {
			return "", "", listErr
		}
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return "", "", err
		}
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	}
	return "", "", fmt.Errorf("unexpected args")
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
func openAll(feature string) {
	internal.RequireTool("tmux")

	featurePath := internal.FeaturePath(feature)
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("Feature not found: %s\n", feature)
		os.Exit(1)
	}

	session := sanitizeSessionName(feature)

	// Kill existing session if any
	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	// Create session with feature dir as first window
	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"))

	// Add a window for each active worktree
	branches := internal.ListBranches(feature)
	for _, branch := range branches {
		wtPath := internal.WorktreePath(feature, branch)
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue // archived
		}
		windowName := sanitizeSessionName(branch)
		_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
	}

	// Select the orchestrator window
	_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")

	// Attach
	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func openWithTmux(feature, branch, path string) {
	internal.RequireTool("tmux")

	session := sanitizeSessionName(feature + "/" + branch)

	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path))

	fmt.Printf("Running: %s\n", agentCmd)
	internal.Must(internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"))

	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	return internal.SanitizeTmuxName(s)
}

func isClaudeAgent(cmd string) bool {
	fields := strings.Fields(cmd)
	if len(fields) == 0 {
		return false
	}
	base := fields[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			oldName := args[0]
			newName := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			root := ws.MetadataRoot

			var oldPath, newPath string
			oldPath, err = ws.ResolveFeaturePath(oldName)
			if err != nil {
				return err
			}
			newPath = ws.FeaturePath(newName)

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", oldName)
			}

			// One locked read validates both names and stages the registry
			// rewrite. It runs before the destination-collision check so a
			// registered space directory reports the space conflict rather
			// than "feature already exists". With no spaces.yaml this is a
			// true no-op: no lock file, no registry file, nothing created.
			tx, err := internal.BeginSpacesFeatureRename(root, oldName, newName, oldPath, newPath)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, tx.Release()) }()

			if _, err := os.Stat(newPath); err == nil {
				return fmt.Errorf("feature already exists: %s", newName)
			}

			// External direct session records must not silently relocate: a
			// whole-directory rename would move every record so its recorded
			// feature and its <branch-id> hash disagree with its location.
			// Checkout mode never writes or reads them.
			if ws.Mode == internal.ModeExternal {
				targets, terr := directRecordTargetsForFeature(oldPath)
				if terr != nil {
					return terr
				}
				if gerr := guardDirectRecords(cmd.OutOrStdout(), oldPath, "rename feature", oldName, targets); gerr != nil {
					return gerr
				}
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				return fmt.Errorf("error renaming: %w", err)
			}

			if commitErr := tx.Commit(); commitErr != nil {
				if rollbackErr := os.Rename(newPath, oldPath); rollbackErr != nil {
					return errors.Join(commitErr, fmt.Errorf(
						"rollback failed: feature directory is now %s on disk while %s still refers to %q; repair with 'tws space remove' and 'tws space add': %w",
						newPath, internal.SpacesFilePath(root), oldName, rollbackErr))
				}
				return commitErr
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
			return nil
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if ws.Mode == internal.ModeCheckout {
				return renameBranchCheckout(ws, feature, oldName, newName)
			}
			return renameBranchExternal(feature, oldName, newName)
		},
	}
}

// renameBranchCheckout renames a branch in checkout mode.
// Uses entry.GitBranch() for git operations (honoring prefixes).
// Short Name is the metadata identity; git branch may have a prefix.
// Metadata is updated only after git succeeds; rolled back if SaveStack fails.
func renameBranchCheckout(ws internal.Workspace, feature, oldName, newName string) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	entry := internal.GetBranch(stack, oldName)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	oldGitBranch := entry.GitBranch()

	// Compute new git branch name: preserve prefix structure.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	// Git rename using GitBranch() (the actual branch name, possibly prefixed).
	if err := internal.RunDir(ws.RepoRoot, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
		return fmt.Errorf("error renaming git branch %s -> %s: %w", oldGitBranch, newGitBranch, err)
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	// Update Branch field if the new git branch differs from the new name.
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		if rollbackErr := internal.RunSilentDir(ws.RepoRoot, "git", "branch", "-m", newGitBranch, oldGitBranch); rollbackErr != nil {
			return fmt.Errorf("error saving stack: %w; rollback of git branch also failed: %v", err, rollbackErr)
		}
		return fmt.Errorf("error saving stack (git branch rolled back): %w", err)
	}

	// Update decisions.yaml branch references.
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// renameBranchExternal renames a branch in external mode.
// Uses entry.GitBranch() for git operations.
func renameBranchExternal(feature, oldName, newName string) error {
	if err := internal.GuardFeatureName(internal.TwsRoot(), feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	if !internal.HasBranch(stack, oldName) {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	// Renaming a branch changes <branch-id>, name, git_branch, and the
	// worktree path, so no record may survive the rewrite.
	if gerr := guardDirectRecords(os.Stdout, featurePath, "rename branch", feature+"/"+oldName,
		directRecordTargetForBranch(feature, oldName)); gerr != nil {
		return gerr
	}

	entry := internal.GetBranch(stack, oldName)
	oldGitBranch := entry.GitBranch()

	// Compute new git branch name preserving prefix.
	cfg := internal.LoadConfig()
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	gitDir := resolveGitDir(featurePath, stack)
	if gitDir == "" {
		return fmt.Errorf("could not find a git context; run from inside the repo or ensure at least one active worktree exists")
	}

	oldPath := internal.WorktreePath(feature, oldName)
	newPath := internal.WorktreePath(feature, newName)

	if _, err := os.Stat(oldPath); err == nil {
		// Active worktree: remove, rename branch, re-add
		if err := internal.RunDir(gitDir, "git", "worktree", "remove", "--force", oldPath); err != nil {
			return fmt.Errorf("error removing worktree: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			_ = internal.RunDir(gitDir, "git", "worktree", "add", oldPath, oldGitBranch)
			return fmt.Errorf("error renaming git branch: %w", err)
		}
		if err := internal.RunDir(gitDir, "git", "worktree", "add", newPath, newGitBranch); err != nil {
			return fmt.Errorf("error creating new worktree: %w", err)
		}

		target := internal.ResolveInjectInto("")
		if injectErr := internal.InjectFiles(featurePath, newPath, target); injectErr != nil {
			fmt.Printf("Warning: inject failed: %v\n", injectErr)
		}
	} else {
		// Archived: just rename the git branch
		if err := internal.RunDir(gitDir, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			return fmt.Errorf("error renaming git branch: %w", err)
		}
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}

	// Kill stale tmux session
	oldSession := sanitizeSessionName(feature + "/" + oldName)
	if sessionExists(oldSession) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
	}

	// Update decisions.yaml branch references
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

// resolveGitDir finds a usable git directory from the feature's worktrees.
// Returns the path to an active worktree, or tries cwd as fallback.
func resolveGitDir(featurePath string, stack internal.Stack) string {
	// Try active worktrees first
	for _, entry := range stack.Branches {
		// Reconstruct from featurePath directly
		path := featurePath + "/worktrees/" + entry.Name
		if _, err := os.Stat(path); err == nil {
			return path
		}
		if entry.Repo != "" {
			return entry.Repo
		}
	}

	// Fallback: try cwd
	if internal.BranchExists("HEAD") {
		cwd, _ := os.Getwd()
		return cwd
	}

	return ""
}

package cli

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// captureStdout captures os.Stdout for commands that print with bare fmt.
func captureStdout(t *testing.T, fn func()) string {
	t.Helper()
	orig := os.Stdout
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = w

	done := make(chan string, 1)
	go func() {
		var buf bytes.Buffer
		_, _ = io.Copy(&buf, r)
		done <- buf.String()
	}()

	fn()

	os.Stdout = orig
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	out := <-done
	if err := r.Close(); err != nil {
		t.Fatal(err)
	}
	return out
}

// writeSpaces writes a spaces.yaml fixture into root.
func writeSpaces(t *testing.T, root, content string) {
	t.Helper()
	if err := os.MkdirAll(root, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "spaces.yaml"), []byte(content), 0600); err != nil {
		t.Fatal(err)
	}
}

// withUnifiedWorkspaceEnv isolates the environment so that TwsRoot() and
// ws.MetadataRoot name the same external root (criterion 20).
func withUnifiedWorkspaceEnv(t *testing.T, repo string) string {
	t.Helper()
	t.Setenv("HOME", t.TempDir())
	t.Setenv("TWS_ROOT", "")
	t.Setenv("XDG_DATA_HOME", t.TempDir())
	oldCWD, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(repo); err != nil {
		t.Fatal(err)
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		t.Fatal(err)
	}
	if ws.MetadataRoot != internal.TwsRoot() {
		t.Fatalf("roots diverge: %s vs %s", ws.MetadataRoot, internal.TwsRoot())
	}
	return ws.MetadataRoot
}

// snapshotTreeIgnoringLock is snapshotTree without the advisory lock file,
// which a transaction legitimately creates once a registry exists.
func snapshotTreeIgnoringLock(t *testing.T, dir string) string {
	t.Helper()
	var kept []string
	for _, line := range strings.Split(snapshotTree(t, dir), "\n") {
		if filepath.Base(line) == ".spaces.lock" {
			continue
		}
		kept = append(kept, line)
	}
	return strings.Join(kept, "\n")
}

func registeredLearningFixture(name string) string {
	return fmt.Sprintf(`version: 1
spaces:
  - name: notes
    kind: learning
    path: %s
    added_at: 2026-01-01T00:00:00Z
`, name)
}

// malformedSpacesFixtures installs one untrusted spaces.yaml variant.
// Permission-based fixtures are deliberately not used.
func malformedSpacesFixtures() []struct {
	name    string
	install func(t *testing.T, root string)
} {
	return []struct {
		name    string
		install func(t *testing.T, root string)
	}{
		{"bad-yaml", func(t *testing.T, root string) { writeSpaces(t, root, "version: 1\nspaces: [\n") }},
		{"version-zero", func(t *testing.T, root string) { writeSpaces(t, root, "version: 0\nspaces: []\n") }},
		{"future-version", func(t *testing.T, root string) { writeSpaces(t, root, "version: 99\nspaces: []\n") }},
		{"unknown-field", func(t *testing.T, root string) { writeSpaces(t, root, "version: 1\nspaces: []\nextra: 1\n") }},
		{"symlinked-file", func(t *testing.T, root string) {
			t.Helper()
			if err := os.MkdirAll(root, 0755); err != nil {
				t.Fatal(err)
			}
			real := filepath.Join(root, "real.yaml")
			if err := os.WriteFile(real, []byte("version: 1\nspaces: []\n"), 0600); err != nil {
				t.Fatal(err)
			}
			if err := os.Symlink(real, filepath.Join(root, "spaces.yaml")); err != nil {
				t.Fatal(err)
			}
		}},
		{"directory", func(t *testing.T, root string) {
			t.Helper()
			if err := os.MkdirAll(filepath.Join(root, "spaces.yaml"), 0755); err != nil {
				t.Fatal(err)
			}
		}},
	}
}

// ---------- feature listing exclusion ----------

func TestSpaceGuard_ListAndDoctorHideRegisteredSpaces(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)

	if err := createWorktree("real", "root", "master", repo, false); err != nil {
		t.Fatal(err)
	}
	mustMkdir(t, filepath.Join(root, "learning"))
	writeSpaces(t, root, registeredLearningFixture("learning"))

	ws, err := internal.RequireWorkspace()
	if err != nil {
		t.Fatal(err)
	}
	features, err := ws.ListFeaturesResolved()
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range features {
		if f == "learning" {
			t.Fatal("registered space appeared as a phantom feature")
		}
	}

	out := captureStdout(t, func() {
		cmd := listCmd()
		cmd.SetArgs(nil)
		if err := cmd.Execute(); err != nil {
			t.Errorf("list: %v", err)
		}
	})
	if strings.Contains(out, "learning") {
		t.Fatalf("tws list showed the registered space:\n%s", out)
	}

	if names := internal.ListFeatures(); contains(names, "learning") {
		t.Fatalf("completion offered the registered space: %v", names)
	}
}

func contains(values []string, want string) bool {
	for _, v := range values {
		if v == want {
			return true
		}
	}
	return false
}

// ---------- logical name guards ----------

func TestSpaceGuard_ExternalCommandMatrix(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)

	if err := addExternal("foo", nil, "", "", false, false, false); err != nil {
		t.Fatal(err)
	}
	learning := mustMkdir(t, filepath.Join(root, "learning"))
	writeSpaces(t, root, registeredLearningFixture("learning"))
	before := snapshotTreeIgnoringLock(t, root)

	cases := []struct {
		name string
		run  func() error
	}{
		{"add", func() error { return addExternal("learning", nil, "", "", false, false, false) }},
		{"new", func() error { return createWorktree("learning", "wt", "master", repo, false) }},
		{"archive", func() error { return archiveExternal("learning", "wt") }},
		{"delete", func() error { return deleteExternal("learning", false, false) }},
		{"rename-feature-target", func() error {
			cmd := renameCmd()
			cmd.SetArgs([]string{"feature", "foo", "learning"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			return cmd.Execute()
		}},
