func TestSpaceGuard_StrictFailureExternal(t *testing.T) {
	for _, fixture := range malformedSpacesFixtures() {
		t.Run(fixture.name, func(t *testing.T) {
			repo := setupGitRepo(t, "master")
			root := withUnifiedWorkspaceEnv(t, repo)
			mustMkdir(t, root)
