func TestSpaceGuard_TemplateSyncAndHooksInstallCarveOutBoundary(t *testing.T) {
	repo := setupGitRepo(t, "master")
	root := withUnifiedWorkspaceEnv(t, repo)
	if err := addExternal("alpha", nil, "", "", false, false, false); err != nil {
		t.Fatal(err)
	}

	t.Run("invalid-name-promoted", func(t *testing.T) {
		// An unusable feature name is refused by the shared guard before the
		// void helper runs, so it exits nonzero with the canonical message
		// and prints no per-feature line. The name can never denote a real
		// feature, and both commands join it under a root.
		var err error
		out := captureStdout(t, func() {
			cmd := templateCmd()
			cmd.SetArgs([]string{"sync", "state"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			err = cmd.Execute()
		})
		if err == nil || err.Error() != `feature name "state" conflicts with reserved directory` {
			t.Fatalf("template sync err = %v", err)
		}
		if strings.Contains(out, "state: ") {
			t.Fatalf("the void helper must not run: %q", out)
		}

		out = captureStdout(t, func() {
			cmd := hooksCmd()
			cmd.SetArgs([]string{"install", "../outside"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			err = cmd.Execute()
		})
		if err == nil || err.Error() != `feature name "../outside" contains path separator` {
			t.Fatalf("hooks install err = %v", err)
		}
		if strings.Contains(out, "[x] ") {
			t.Fatalf("the void helper must not run: %q", out)
		}
	})

	t.Run("unrelated-failure-preserved", func(t *testing.T) {
		// A failing RequireWorkspace in template sync is still not promoted:
		// the void helper owns it, keeping the stdout line and exit 0.
		outside := t.TempDir()
		oldCWD, _ := os.Getwd()
		t.Cleanup(func() { _ = os.Chdir(oldCWD) })
		chdirForTest(t, outside)
		t.Setenv("HOME", t.TempDir())
		t.Setenv("TWS_ROOT", "")

		var err error
		out := captureStdout(t, func() {
			cmd := templateCmd()
			cmd.SetArgs([]string{"sync", "alpha"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			err = cmd.Execute()
		})
		if err != nil {
			t.Fatalf("expected exit 0, got %v", err)
		}
		if !strings.Contains(out, "alpha: ") {
			t.Fatalf("expected legacy stdout line, got %q", out)
		}
	})

	t.Run("all-branch-unchanged", func(t *testing.T) {
		mustMkdir(t, filepath.Join(root, "learning"))
		writeSpaces(t, root, registeredLearningFixture("learning"))

		var err error
		out := captureStdout(t, func() {
			cmd := templateCmd()
			cmd.SetArgs([]string{"sync", "--all"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			err = cmd.Execute()
		})
		if err != nil {
			t.Fatalf("--all must still exit 0, got %v", err)
		}
		if strings.Contains(out, "top-level directory of registered space") {
			t.Fatalf("--all must carry no per-feature guard:\n%s", out)
		}
		if !strings.Contains(out, "alpha:") {
			t.Fatalf("expected per-feature progress lines:\n%s", out)
		}

		out = captureStdout(t, func() {
			cmd := hooksCmd()
			cmd.SetArgs([]string{"install", "--all"})
			cmd.SetOut(io.Discard)
			cmd.SetErr(io.Discard)
			err = cmd.Execute()
		})
		if err != nil {
			t.Fatalf("--all must still exit 0, got %v", err)
		}
		if strings.Contains(out, "top-level directory of registered space") {
			t.Fatalf("--all must carry no per-feature guard:\n%s", out)
		}
	})
}

