func TestSpaceAddValidationErrors(t *testing.T) {
	root := t.TempDir()
	anchor := testAnchor(t, root, ModeExternal)
	target := filepath.Join(root, "learning")
	if err := os.MkdirAll(target, 0755); err != nil {
		t.Fatal(err)
	}
